<!doctype html><html><head><meta charset="utf-8"><title>{{ $order->number }}</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:14px Arial;max-width:850px;margin:35px auto;padding:0 16px}header{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;border-bottom:2px solid;padding-bottom:15px}.print-table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;margin-top:25px;min-width:480px}th,td{padding:10px;border:1px solid #bbb;text-align:left}@media print{button{display:none}}@media(max-width:600px){body{margin:18px auto;font-size:13px}}</style></head><body><header><h1>{{ $businessSettings->site_name }}</h1><h2>{{ $order->number }}</h2></header><p>{{ $order->customerName() }} · {{ $order->phone }}<br>{{ $order->city }}, {{ $order->address }}<br>Трек: {{ $order->tracking_number ?: '—' }}</p><div class="print-table-wrap"><table><tr><th>Товар</th><th>Продавец</th><th>Кол-во</th><th>Сумма</th></tr>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}</td><td>{{ $item->seller?->store_name ?: $businessSettings->site_name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->price*$item->quantity,0,'',' ') }}</td></tr>@endforeach</table></div><h2 style="text-align:right">Итого: {{ number_format($order->total,0,'',' ') }} {{ $businessSettings->currency }}</h2><button onclick="print()">Печать</button></body></html>
